    private FireballCoreMesh() {
    }

    public static void render(PoseStack pose, MultiBufferSource buffer, float scale) {
        pose.pushPose();
        pose.scale(scale, scale, scale);
        pose.translate(-0.5F, -0.5F, -0.5F);
        VertexConsumer vc = buffer.getBuffer(TYPE);
        var mat = pose.last().pose();
        for (float[] q : QUADS) {
            for (int i = 0; i < 4; i++) {
                float x = q[i * 5];
                float y = q[i * 5 + 1];
                float z = q[i * 5 + 2];
                vc.vertex(mat, x, y, z)
                        .color(255, 255, 255, 255)
                        .uv(q[i * 5 + 3], q[i * 5 + 4])
                        .overlayCoords(OverlayTexture.NO_OVERLAY)
                        .uv2(LightTexture.FULL_BRIGHT)
                        .normal(0.0F, 1.0F, 0.0F)
                        .endVertex();
            }
        }
        pose.popPose();
    }
